import axios from 'axios';
const client = axios.create({ baseURL: import.meta.env.VITE_API_URL || '' });
client.interceptors.request.use((config) => { const token = localStorage.getItem('smarthvac_token'); if (token) config.headers.Authorization = `Bearer ${token}`; return config; });
export const setToken = (token: string | null) => token ? localStorage.setItem('smarthvac_token', token) : localStorage.removeItem('smarthvac_token');
export async function login(email: string, password: string) { const { data } = await client.post('/api/auth/login', { email, password }); return data; }
export const api = { dashboard: async () => (await client.get('/api/dashboard')).data, buildings: async () => (await client.get('/api/buildings')).data, locations: async () => (await client.get('/api/buildings/locations')).data, environment: async (buildingCode?: string) => (await client.get('/api/environment', { params: buildingCode ? { building_code: buildingCode } : undefined })).data, hvac: async () => (await client.get('/api/hvac')).data, sensors: async () => (await client.get('/api/sensors')).data, control: async (id: string, payload: object) => (await client.post(`/api/hvac/${id}/control`, payload)).data, energy: async () => (await client.get('/api/energy/summary')).data, alerts: async () => (await client.get('/api/alerts')).data, acknowledge: async (id: string) => (await client.post(`/api/alerts/${id}/acknowledge`)).data, chat: async (message: string) => (await client.post('/api/ai/chat', { message })).data, users: async () => (await client.get('/api/users')).data, createUser: async (payload: object) => (await client.post('/api/users', payload)).data };
